/* diary-plus.js — «Дневник+» для FitSim
   0) Замеры тела и история замеров (перенесены из pages.js): форма с манекеном,
      история по месяцам, график, голосовой ввод, резервная копия.
   1) Отчёт тренеру  2) Заметка о самочувствии
   3) «Повторить тренировку»  4) Динамика замеров
   Подключать ПОСЛЕДНИМ, после pages.js и ai-couch.js. */

/* ══ 0. Замеры тела (перенесено из pages.js без изменений логики) ══ */
function normalizeBodyDate(value) {
  const text = String(value || '').trim();
  if (!text) return '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
  let match = text.match(/^(\d{1,2})[.\/](\d{1,2})[.\/](\d{4})/);
  if (match) return `${match[3]}-${String(match[2]).padStart(2, '0')}-${String(match[1]).padStart(2, '0')}`;
  match = text.match(/^(\d{4})[.\/](\d{1,2})[.\/](\d{1,2})/);
  if (match) return `${match[1]}-${String(match[2]).padStart(2, '0')}-${String(match[3]).padStart(2, '0')}`;
  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? '' : getLocalISODate(parsed);
}

function normalizeBodyEntry(entry) {
  if (!entry || typeof entry !== 'object') return null;
  const date = normalizeBodyDate(entry.date) || getLocalISODate();
  const normalized = { date };
  ['weight', 'neck', 'shoulders', 'chest', 'bicepLeft', 'bicepRight', 'forearmLeft', 'forearmRight', 'waist', 'glutes', 'thighLeft', 'thighRight', 'calfLeft', 'calfRight', 'bicep', 'forearm', 'thigh', 'calf'].forEach(key => {
    const raw = String(entry[key] ?? '').trim().replace(',', '.');
    const value = Number(raw);
    if (raw !== '' && Number.isFinite(value) && value >= 0) normalized[key] = value;
  });
  ['bicep','forearm','thigh','calf'].forEach(key=>{if(normalized[key+'Right']===undefined&&normalized[key]>0)normalized[key+'Right']=normalized[key];});
  return Object.keys(normalized).length > 1 ? normalized : null;
}

function refreshBodyStorage() {
  try {
    const rawWeight = JSON.parse(localStorage.getItem('fs-wlog') || '[]');
    const rawBody = JSON.parse(localStorage.getItem('fs-bodylog') || '[]');
    wlog = Array.isArray(rawWeight) ? rawWeight.map(normalizeBodyEntry).filter(Boolean).map(e => ({ date:e.date, weight:e.weight, id:e.id || e.date })).filter(e => e.weight) : [];
    bodyLog = Array.isArray(rawBody) ? rawBody.map(normalizeBodyEntry).filter(Boolean) : [];
  } catch (error) {
    wlog = Array.isArray(wlog) ? wlog : [];
    bodyLog = Array.isArray(bodyLog) ? bodyLog : [];
  }
}

function exportBodyBackup() {
  refreshBodyStorage();
  const blob = new Blob([JSON.stringify({ wlog, bodyLog }, null, 2)], { type:'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url; link.download = 'fitsim-zamery.json'; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
window.exportBodyBackup = exportBodyBackup;

function importBodyBackup() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'application/json,.json';
  input.onchange = event => {
    const file = event.target.files && event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result);
        const weights = Array.isArray(data.wlog) ? data.wlog : Array.isArray(data['fs-wlog']) ? data['fs-wlog'] : [];
        const measurements = Array.isArray(data.bodyLog) ? data.bodyLog : Array.isArray(data['fs-bodylog']) ? data['fs-bodylog'] : [];
        if (!weights.length && !measurements.length) throw new Error('empty');
        localStorage.setItem('fs-wlog', JSON.stringify(weights));
        localStorage.setItem('fs-bodylog', JSON.stringify(measurements));
        refreshBodyStorage();
        renderBodyLog();
        toast('✅ Замеры импортированы');
      } catch (error) { toast('❗ Не удалось прочитать файл замеров'); }
    };
    reader.readAsText(file);
  };
  input.click();
}
window.importBodyBackup = importBodyBackup;

let bodyLogRetryTimer = null;
function renderBodyLog() {
  const c = document.getElementById('body-log');
  if (!c) { if (!bodyLogRetryTimer) bodyLogRetryTimer = setTimeout(() => { bodyLogRetryTimer = null; renderBodyLog(); }, 80); return; }
  refreshBodyStorage();
  const labels = { neck:'Шея', chest:'Грудь', bicep:'Бицепс', forearm:'Предплечье', waist:'Талия', glutes:'Ягодицы', thigh:'Бедро', calf:'Икра' };
  const byDate = new Map();
  bodyLog.forEach(e => byDate.set(e.date, { ...(byDate.get(e.date) || {}), ...e }));
  wlog.forEach(e => byDate.set(e.date, { ...(byDate.get(e.date) || {}), date:e.date, weight:e.weight, weightId:e.id }));
  const entries = [...byDate.values()].sort((a, b) => b.date.localeCompare(a.date));
  const lastEl = document.getElementById('diary-last-body'), chartCard = document.getElementById('body-chart-card');
  if (lastEl) lastEl.innerHTML = entries[0] ? `<div class="diary-last-date">${formatBodyDate(entries[0].date)}</div>` : '<div class="diary-empty">Пока нет замеров</div>';
  if (chartCard) chartCard.style.display = entries.length >= 2 ? '' : 'none';
  const historySection=c.closest('.diary-measurements-history');
  if(historySection){historySection.hidden=!entries.length;historySection.style.display=entries.length?'':'none';}
  if (!entries.length) { c.innerHTML = ''; renderBodyChart(); return; }
  const months = ['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'], groups = new Map();
  entries.forEach(e => { const [year, month] = e.date.split('-'), key = `${year}-${month}`; if (!groups.has(key)) groups.set(key, { key, title:`${year} ${months[+month - 1]}`, entries:[] }); groups.get(key).entries.push(e); });
  c.innerHTML = [...groups.values()].map(g => `<section class="body-month-group"><button type="button" class="body-month-head is-collapsed" onclick="toggleBodyMonth('${g.key}', this)" aria-expanded="false"><span>${g.title}</span><small>${g.entries.length} ${bodyEntryWord(g.entries.length)}</small><i>⌃</i></button><div class="body-month-rows is-collapsed" id="body-month-${g.key}">${g.entries.map((e,i) => bodyEntryHtml(e, null, labels, entries)).join('')}</div></section>`).join('');
  renderBodyChart();
}
function bodyEntryWord(n) { const r=n%10,h=n%100; return r===1&&h!==11?'замер':r>=2&&r<=4&&!(h>=12&&h<=14)?'замера':'замеров'; }
const BODY_SIDE_METRICS={neck:'Шея',shoulders:'Плечи',chest:'Грудь',bicepLeft:'Л · Бицепс',bicepRight:'П · Бицепс',forearmLeft:'Л · Предплечье',forearmRight:'П · Предплечье',waist:'Талия',glutes:'Ягодицы',thighLeft:'Л · Бедро',thighRight:'П · Бедро',calfLeft:'Л · Голень',calfRight:'П · Голень',weight:'Вес'};
const BODY_MAP_ROWS=[['neck','weight'],['chest','shoulders'],['bicepRight','bicepLeft'],['forearmRight','forearmLeft'],['glutes','waist'],['thighRight','thighLeft'],['calfRight','calfLeft']];
function bodyMetricPresent(e,k){return !!e&&e[k]!==undefined&&e[k]!==null&&e[k]!==''&&Number.isFinite(Number(e[k]))&&Number(e[k])>0;}
function bodyEntryHtml(e,prev,labels,entries){
 const history=Array.isArray(entries)?entries:prev?[e,prev]:[e],goal=(typeof profile!=='undefined'&&profile&&profile.goal)||'';
 const weights=history.filter(row=>bodyMetricPresent(row,'weight')),first=weights[weights.length-1],latest=weights[0];
 let map='';
 BODY_MAP_ROWS.forEach((cells,row)=>cells.forEach((key,col)=>{
  if(!key)return;const present=bodyMetricPresent(e,key),unit=key==='weight'?'кг':'см',value=present?Number(e[key]):null;
  const previous=history.find(item=>item.date<e.date&&bodyMetricPresent(item,key));
  const delta=present&&previous?Math.round((value-Number(previous[key]))*10)/10:null;
  let badge='';
  if(delta!==null){let tone=delta===0?'flat':'neutral';if(delta&&key==='weight'&&(goal==='loss'||goal==='gain'))tone=((goal==='loss'&&delta<0)||(goal==='gain'&&delta>0))?'good':'bad';
   const text=delta===0?'±0':(delta>0?'↑':'↓')+Math.abs(delta).toLocaleString('ru-RU');
   const description=`${delta>0?'+':''}${delta.toLocaleString('ru-RU')} ${unit} к замеру от ${formatBodyDate(previous.date)}`;
   badge=`<span class="bm-delta ${tone}" title="${description}" aria-label="${description}">${text}</span>`;
  }
  map+=`<div class="bm-metric ${key==='weight'?'bm-weight':''} ${present?'':'bm-missing'}" data-metric="${key}" style="grid-column:${col+1};grid-row:${row+1}"><span class="bm-label">${BODY_SIDE_METRICS[key]}</span><div class="bm-value" ${present?'':'aria-label="Нет замера"'}>${present?value.toLocaleString('ru-RU'):'—'}${present?` <small>${unit}</small>`:''}</div>${badge}</div>`;
 }));
 let total='';if(bodyMetricPresent(e,'weight')&&latest&&latest.date===e.date&&first&&first.date!==e.date){const d=Math.round((Number(e.weight)-Number(first.weight))*10)/10;total=`<div class="bm-map-total"><span>С первого взвешивания</span><strong>${d>0?'+':d===0?'±':''}${d.toLocaleString('ru-RU')} <small>кг</small></strong><small>от ${formatBodyDate(first.date)}</small></div>`;}
 const date=new Date(e.date+'T00:00:00'),day=Number.isNaN(date.getTime())?'Замеры тела':date.toLocaleDateString('ru-RU',{weekday:'long'});
 return `<article class="bm-entry"><header class="bm-entry-head"><div><span class="bm-eyebrow">${day.charAt(0).toUpperCase()+day.slice(1)}</span><h3>${formatBodyDate(e.date)}</h3></div><button type="button" class="bm-delete" aria-label="Удалить замеры за ${formatBodyDate(e.date)}" onclick="delBody('${e.date}')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button></header><div class="bm-map">${map}</div>${total}</article>`;
}
function toggleBodyMonth(key, button) { const rows=document.getElementById(`body-month-${key}`); if(!rows)return; const closed=rows.classList.toggle('is-collapsed'); button.classList.toggle('is-collapsed',closed); button.setAttribute('aria-expanded',String(!closed)); }
window.toggleBodyMonth=toggleBodyMonth;
function delBody(date) {
  confirmDanger({
    title: 'Удалить замеры?',
    message: '',
    compact: true,
    onConfirm: () => {
  bodyLog = bodyLog.filter(e => e.date !== date);
  wlog = wlog.filter(e => e.date !== date);
  localStorage.setItem('fs-bodylog', JSON.stringify(bodyLog));
  localStorage.setItem('fs-wlog', JSON.stringify(wlog));
  renderBodyLog();
  toast('🗑 Запись удалена');
}
  });
}
window.delBody = delBody;
window.delWeight = delBody;


function getLocalISODate(date = new Date()) {
  const offset = date.getTimezoneOffset() * 60 * 1000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 10);
}

function formatBodyDate(value) {
  const parts = String(value || '').split('-');
  if (parts.length !== 3) return value ? String(value) : 'Без даты';
  const date = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString('ru-RU', {
    day: 'numeric', month: 'long', year: 'numeric'
  });
}

let bodyMeasureReturnScroll={windowY:0,areaY:0};
function ensureBodyMeasurementPage(){
 const sheet=document.getElementById('body-sheet'),area=document.querySelector('.scroll-area');
 if(!sheet||!area)return null;
 let page=document.getElementById('page-bodymeasure');
 if(!page){page=document.createElement('section');page.id='page-bodymeasure';page.className='page body-measure-page';page.setAttribute('aria-label','Замеры тела');area.appendChild(page);}
 if(sheet.parentElement!==page)page.appendChild(sheet);
 sheet.classList.remove('bottom-sheet','bf-keyboard-editing');
 sheet.classList.add('body-measure-menu-content');
 ['translate','transform','transition','top','bottom','height','max-height','--bf-visible-top','--bf-visible-height'].forEach(name=>sheet.style.removeProperty(name));
 let actions=document.getElementById('body-measure-actions')||sheet.querySelector('.bf-footer');
 if(actions){actions.id='body-measure-actions';actions.hidden=true;if(actions.parentElement!==document.body)document.body.appendChild(actions);}
 return sheet;
}
function openBodySheet() {
  setupBodySidesForm();stopBodyVoice();
  const area=document.querySelector('.scroll-area');
  bodyMeasureReturnScroll={windowY:window.scrollY||0,areaY:area?.scrollTop||0};
  const sheet=ensureBodyMeasurementPage();if(!sheet)return;
  document.getElementById('sheet-overlay')?.classList.remove('show');
  const status=document.getElementById('body-voice-status');if(status)status.textContent='';
  document.getElementById('sb-date').value=getLocalISODate();
  ['neck','shoulders','chest','bicepLeft','bicepRight','forearmLeft','forearmRight','waist','glutes','thighLeft','thighRight','calfLeft','calfRight','weight'].forEach(key=>{const input=document.getElementById('sb-'+key);if(input)input.value='';});
  bodyFigureSelected=null;renderBodyFigure();
  const details=sheet.querySelector('.bf-all-fields');if(details)details.open=false;
  sheet.classList.add('show');
  goTo('bodymeasure','Замеры тела');
  if(area)area.scrollTop=0;
}
function exitBodyMeasurements(force=false){
 const sheet=document.getElementById('body-sheet');
 const hasData=sheet&&Array.from(sheet.querySelectorAll('input[id^="sb-"][type="number"]')).some(input=>input.value!=='');
 if(!force&&hasData){confirmDanger({title:'Выйти без сохранения?',message:'',compact:true,confirmText:'Выйти',onConfirm:()=>exitBodyMeasurements(true)});return;}
 stopBodyVoice();
 if(sheet){if(sheet.contains(document.activeElement))document.activeElement.blur();sheet.classList.remove('show');}
 document.getElementById('sheet-overlay')?.classList.remove('show');
 goTo('diary','Дневник');
 requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(()=>{
  if(currentPage!=='diary')return;
  const area=document.querySelector('.scroll-area');if(area)area.scrollTop=bodyMeasureReturnScroll.areaY;
  window.scrollTo(0,bodyMeasureReturnScroll.windowY);
 })));
}
window.exitBodyMeasurements=exitBodyMeasurements;
window.openBodySheet = openBodySheet;

function addBody() {
  stopBodyVoice();
  const bodyInputs=document.querySelectorAll('#body-sheet input[id^="sb-"][type="number"]');
  for(const input of bodyInputs){if(input.validity.badInput||(input.value!==''&&(!Number.isFinite(Number(input.value))||Number(input.value)<=0||Number(input.value)>999))){toast('Укажи число больше 0 и не больше 999');input.focus();return;}}
  refreshBodyStorage();
  const d = document.getElementById('sb-date').value || getLocalISODate();
  const entry = { date: d };
  const keys = ['neck', 'shoulders', 'chest', 'bicepLeft', 'bicepRight', 'forearmLeft', 'forearmRight', 'waist', 'glutes', 'thighLeft', 'thighRight', 'calfLeft', 'calfRight'];
  let hasData = false;

  keys.forEach(k => {
    const inp = document.getElementById('sb-' + k);
    const v = parseFloat(inp.value);
    if (inp.value !== '' && !isNaN(v)) {
      entry[k] = v;
      hasData = true;
    }
  });

  const weightVal = parseFloat(document.getElementById('sb-weight').value);
  if (Number.isFinite(weightVal) && weightVal > 0) {
    const wExists = wlog.findIndex(e => e.date === d);
    if (wExists !== -1) wlog[wExists].weight = weightVal;
    else wlog.push({ date: d, weight: weightVal, id: Date.now() });
    localStorage.setItem('fs-wlog', JSON.stringify(wlog));
    hasData = true;
  }

  if (!hasData) {
    toast('❗ Заполни хотя бы одно поле');
    return;
  }

  const hasBodyData = keys.some(k => entry[k] !== undefined);
  if (hasBodyData) {
    const exists = bodyLog.findIndex(e => e.date === d);
    if (exists !== -1) bodyLog[exists] = {...bodyLog[exists], ...entry};
    else bodyLog.push(entry);
    localStorage.setItem('fs-bodylog', JSON.stringify(bodyLog));
  }

  refreshBodyStorage();
  renderBodyLog();
  exitBodyMeasurements(true);
  toast('✅ Замеры сохранены');
}
window.addBody = addBody;

function renderBodyChart() {
  const card = document.getElementById('body-chart-card');
  const el = document.getElementById('body-chart-canvas');
  const sel = document.getElementById('body-chart-metric');
  if (!el || !sel) return;
  const names = {weight:'Вес', waist:'Талия', chest:'Грудь', shoulders:'Плечи', neck:'Шея', bicepLeft:'Бицепс левый', bicepRight:'Бицепс правый', forearmLeft:'Предплечье левое', forearmRight:'Предплечье правое', glutes:'Ягодицы', thighLeft:'Бедро левое', thighRight:'Бедро правое', calfLeft:'Голень левая', calfRight:'Голень правая'};
  const rowsFor = m => (m === 'weight' ? wlog : bodyLog).filter(e => e && e.date && e[m] !== undefined && e[m] !== null && e[m] !== '' && Number.isFinite(parseFloat(e[m]))).map(e => ({date: e.date, v: parseFloat(e[m])})).sort((a, b) => a.date.localeCompare(b.date));
  const avail = Object.keys(names).filter(m => rowsFor(m).length >= 2);
  const prev = sel.value;
  const optKey = avail.join(',');
  if (sel.dataset.opts !== optKey) {
    sel.innerHTML = avail.map(m => `<option value="${m}">${names[m]}</option>`).join('');
    sel.dataset.opts = optKey;
    sel.value = avail.includes(prev) ? prev : (avail[0] || '');
  }
  const period = window.bodyChartPeriod || 'all';
  document.querySelectorAll('#body-chart-period button').forEach(b => {
    const on = b.dataset.p === period;
    b.style.background = on ? 'var(--accent)' : 'transparent';
    b.style.color = on ? '#fff' : 'var(--text-light)';
  });
  if (!avail.length) { el.innerHTML = '<div style="text-align:center;color:var(--text-light);font-size:13px;padding:16px 0 2px">Добавьте минимум две записи для графика</div>'; return; }
  const metric = sel.value || avail[0];
  let rows = rowsFor(metric);
  if (period !== 'all') {
    const cut = new Date(); cut.setDate(cut.getDate() - parseInt(period, 10));
    const cutIso = cut.getFullYear() + '-' + String(cut.getMonth() + 1).padStart(2, '0') + '-' + String(cut.getDate()).padStart(2, '0');
    rows = rows.filter(r => r.date >= cutIso);
  }
  if (rows.length < 2) { el.innerHTML = '<div style="text-align:center;color:var(--text-light);font-size:13px;padding:16px 0 2px">За выбранный период мало записей</div>'; return; }
  const day = 86400000, ts = rows.map(r => new Date(r.date + 'T12:00:00').getTime());
  const t0 = ts[0], t1 = ts[ts.length - 1], span = (t1 - t0) || 1;
  const vals = rows.map(r => r.v);
  let avg = [];
  if (metric === 'weight') {
    const weeks = new Map();
    rows.forEach((r, i) => {
      const dt = new Date(ts[i]); const k = new Date(ts[i] - ((dt.getDay() + 6) % 7) * day).toISOString().slice(0, 10);
      if (!weeks.has(k)) weeks.set(k, []);
      weeks.get(k).push({t: ts[i], v: r.v});
    });
    avg = [...weeks.values()].map(a => ({t: a.reduce((s, x) => s + x.t, 0) / a.length, v: a.reduce((s, x) => s + x.v, 0) / a.length}));
  }
  const all = vals.concat(avg.map(a => a.v));
  const minV = Math.min(...all), maxV = Math.max(...all), range = (maxV - minV) || 1;
  const W = 280, H = 100, padX = 12, padY = 16;
  const X = t => padX + (t - t0) / span * (W - 2 * padX);
  const Y = v => H - padY - (v - minV) / range * (H - 2 * padY);
  const poly = rows.map((r, i) => `${X(ts[i]).toFixed(1)},${Y(r.v).toFixed(1)}`).join(' ');
  const area = `${X(t0).toFixed(1)},${H - padY} ${poly} ${X(t1).toFixed(1)},${H - padY}`;
  const showLabels = rows.length <= 8;
  const dots = rows.map((r, i) => `<circle cx="${X(ts[i]).toFixed(1)}" cy="${Y(r.v).toFixed(1)}" r="${rows.length > 20 ? 2 : 3.2}" fill="var(--accent)"/>` + (showLabels ? `<text x="${X(ts[i]).toFixed(1)}" y="${(Y(r.v) - 7).toFixed(1)}" text-anchor="middle" font-size="8" fill="var(--text-light)">${r.v}</text>` : '')).join('');
  let avgLine = '';
  if (avg.length >= 2) {
    const ap = avg.map(a => `${X(a.t).toFixed(1)},${Y(a.v).toFixed(1)}`).join(' ');
    avgLine = `<polyline points="${ap}" fill="none" stroke="#f59e0b" stroke-width="2" stroke-dasharray="5 3" stroke-linecap="round" stroke-linejoin="round"/>`;
  }
  const unit = metric === 'weight' ? ' кг' : ' см';
  const diff = Math.round((vals[vals.length - 1] - vals[0]) * 10) / 10;
  const diffTxt = (diff > 0 ? '+' : diff < 0 ? '−' : '') + Math.abs(diff).toString().replace('.', ',') + unit;
  const fmt = iso => iso.split('-').slice(1).reverse().join('.');
  const legend = avgLine ? '<div style="display:flex;gap:12px;font-size:10px;color:var(--text-light);margin-top:6px"><span><b style="color:var(--accent)">●</b> замеры</span><span><b style="color:#f59e0b">- -</b> среднее за неделю</span></div>' : '';
  el.innerHTML = `<div style="font-size:12px;color:var(--text-light);font-weight:600;margin-bottom:6px">${names[metric]}: ${vals[0]} → ${vals[vals.length - 1]}${unit} <span style="color:var(--text)">(${diffTxt})</span></div><svg viewBox="0 0 ${W} ${H + 12}" style="width:100%;overflow:visible"><defs><linearGradient id="bcg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".22"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs><polygon points="${area}" fill="url(#bcg)"/><polyline points="${poly}" fill="none" stroke="var(--accent)" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>${avgLine}${dots}<text x="${X(t0).toFixed(1)}" y="${H + 8}" text-anchor="start" font-size="8" fill="var(--text-light)">${fmt(rows[0].date)}</text><text x="${X(t1).toFixed(1)}" y="${H + 8}" text-anchor="end" font-size="8" fill="var(--text-light)">${fmt(rows[rows.length - 1].date)}</text></svg>${legend}`;
}
window.renderBodyChart = renderBodyChart;
function setBodyChartPeriod(p) { window.bodyChartPeriod = p; renderBodyChart(); }
