 const fields=fieldOrder.map(key=>`<div class="sheet-field"><label for="sb-${key}">${BODY_SIDE_METRICS[key]}, ${key==='weight'?'кг':'см'}</label><input id="sb-${key}" type="number" inputmode="decimal" step="0.1" min="0.1" max="999"></div>`).join('');
