 const values={},allKeys=['neck','weight','chest','shoulders','bicepRight','bicepLeft','forearmRight','forearmLeft','glutes','waist','thighRight','thighLeft','calfRight','calfLeft'];
 const names={weight:'вес(?:а)?',neck:'ше(?:я|ю|и|е|йные|йный|йная)',shoulders:'плечевой пояс|плечи|плечо|плечах|плеч|дельты',chest:'груд(?:ная клетка|ной клетки|ь|и|ью|ные|ных|ная|ной)',waist:'тали(?:я|ю|и|е)|живот',glutes:'ягодиц(?:ы|а|ах)?|попа|попу',bicep:'бицепс(?:ами|ов|а|е|ом|ы)?|бицух(?:а|и|у)',forearm:'предплечь(?:ями|ях|е|я|ю|и|ем)',thigh:'бедр(?:ами|ах|о|а|у|е|ом)|бедер|ляжк(?:а|и|у)',calf:'голен(?:ями|ях|ь|и|ью)|икр(?:ами|ах|а|ы|у)|икроножн(?:ая|ой|ую|ые)'};
 const keys=Object.keys(names),paired=new Set(['bicep','forearm','thigh','calf']);
 const sideWord=String.raw`(?:лев[а-я]*|прав[а-я]*|слева|справа|об[ае]|обоих|обеих|с обеих сторон)`;
