   let targets=[key];if(paired.has(key)){const left=/лев|слева/.test(side),right=/прав|справа/.test(side),both=/об[ае]|обоих|обеих/.test(side)||(left&&right);targets=both?[key+'Left',key+'Right']:[key+(left?'Left':'Right')];}
   if(clear&&!/^\s*(?:[:=]|составляет)?\s*\d/.test(tail)){targets.forEach(k=>values[k]='');continue;}
